  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Wähl einen Song – er läuft zu Hause, bis du ihn ausschaltest oder schlafen gehst. Alle Songs aus Pixelstadt gibt es hier.",
