  "🗼 Solöns fyr har lyst varje natt i över hundra år. Fyrvaktaren sägs ha en båt att hyra ut …": "🗼 Der Leuchtturm der Sonneninsel leuchtet seit über hundert Jahren jede Nacht. Angeblich vermietet der Leuchtturmwärter ein Boot …",
  "🗽 Pixelstadens grundare. Varje vecka får den som skickar flest vänskapspresenter en egen guldstaty här.": "🗽 Der Gründer von Pixelstadt. Jede Woche bekommt hier, wer die meisten Freundschaftsgeschenke verschickt, eine eigene goldene Statue.",
